def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                cells=[]; st=[(i,j)]; seen[i][j]=True
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx] and not seen[ny][nx]:
                                seen[ny][nx]=True; st.append((ny,nx))
                out.append(cells)
    return out
